'use strict';
const Lab={timer:null,cleanup(){if(this.timer)clearInterval(this.timer);this.timer=null;},mount(type,host){this.cleanup();this[type](host);},
greenhouse(host){
 host.innerHTML=`<h2>Greenhouse: read → compare → control</h2><div class="lab-grid"><div><label>Temperature: <output id="temp-out">31</output> °C<input id="temp" type="range" min="0" max="50" value="31"></label><label>Soil moisture: <output id="moisture-out">25</output> %<input id="moisture" type="range" min="0" max="100" value="25"></label><label>Light level: <output id="light-out">60</output> units<input id="light" type="range" min="0" max="100" value="60"></label><label><input type="checkbox" id="sensor-fault"> Simulate missing sensor data</label><div class="lab-controls"><button class="primary" id="green-step">Next step</button><button id="green-auto">Run cycle</button><button id="green-reset">Reset</button></div><p class="source-note">Try 28°C, 35% and 40 units to check the boundaries. After a cycle, change the readings yourself to represent a change in the environment.</p></div><div class="lab-result" id="green-result" aria-live="polite"></div></div>`;
 let stage=0;const el=id=>host.querySelector('#'+id);
 const values=()=>({t:Number(el('temp').value),m:Number(el('moisture').value),l:Number(el('light').value),fault:el('sensor-fault').checked});
 const stop=()=>{this.cleanup();el('green-auto').disabled=false;el('green-step').disabled=false;};
 const draw=()=>{const v=values(),invalid=v.fault||![v.t,v.m,v.l].every(Number.isFinite);['temp','moisture','light'].forEach(id=>el(id+'-out').textContent=el(id).value);
  const labels=['Ready: predict before you run','1 / 4 · Read the data','2 / 4 · Compare with thresholds','3 / 4 · Send signals','4 / 4 · Outputs carry out actions'];
  const decisions=[v.t>28,v.m<35,v.l<40];
  el('green-result').innerHTML=`<h3>${labels[stage]}</h3><p>${stage===0?'No commands have been calculated yet. Change the readings and predict the three outputs.':invalid?'No reliable readings are available. This model stops automatic control and keeps all three commands OFF. Check the sensors.':`Readings: ${v.t}°C · ${v.m}% · ${v.l} units.`}</p>${stage>=2&&!invalid?`<p>${v.t} > 28: <b>${decisions[0]?'true':'false'}</b><br>${v.m} &lt; 35: <b>${decisions[1]?'true':'false'}</b><br>${v.l} &lt; 40: <b>${decisions[2]?'true':'false'}</b></p>`:''}${['Fan','Pump','Lamp'].map((name,i)=>`<div class="status-row"><span>${name}</span><strong>${stage<3?'No command yet':!invalid&&decisions[i]?'ON':'OFF'}</strong></div>`).join('')}${stage===4?'<p style="margin-top:18px">Motors and other outputs carry out the commands. A real control cycle takes new readings to decide what to do next.</p>':''}<small>${invalid?'This fault response is chosen for this activity. A real system needs a safety response suited to its task.':'Sensors measure; the processor compares; actuators create physical effects.'}</small>`;
 };
 const step=()=>{stage=Math.min(4,stage+1);draw();if(stage===4)stop();};
 ['temp','moisture','light','sensor-fault'].forEach(id=>el(id).addEventListener('input',()=>{stop();stage=0;draw();}));
 el('green-step').onclick=()=>{if(stage===4)stage=0;step();};
 el('green-auto').onclick=()=>{stop();stage=0;el('green-auto').disabled=true;el('green-step').disabled=true;step();this.timer=setInterval(step,900);};
 el('green-reset').onclick=()=>{stop();stage=0;el('temp').value=31;el('moisture').value=25;el('light').value=60;el('sensor-fault').checked=false;draw();};draw();
},
robot(host){
 const contexts={warehouse:{title:'Warehouse robot: stop before obstacles and carry boxes',sensor:'Distance sensor',processor:'Controller compares distance with a safe limit',actuator:'Wheel motors',why:'The sensor measures distance. The controller checks the safe limit. The wheel motors stop or move the robot.'},home:{title:'Home robot: detect the edge of stairs',sensor:'Downward-facing cliff sensor',processor:'Controller checks for an edge',actuator:'Wheel motors',why:'The downward-facing sensor detects a change in distance or reflected light at an edge. The controller decides to avoid it. The wheel motors stop or turn the robot.'},farm:{title:'Farm robot: pick a fruit after locating it',sensor:'Camera',processor:'Controller locates the fruit from image data',actuator:'Gripper motor',why:'The camera supplies image data. The controller finds the position. The gripper motor picks the fruit. A camera alone does not show that the robot uses ML.'}};
 const choices={sensor:['Camera','Distance sensor','Downward-facing cliff sensor'],processor:['Controller checks for an edge','Controller locates the fruit from image data','Controller compares distance with a safe limit'],actuator:['Gripper motor','Wheel motors','Speaker']};
 host.innerHTML=`<h2>Explore the parts, then match them to a task</h2><div class="lab-grid"><div><img src="assets/images/05-industrial-robot.png" alt="Industrial robot with an arm, camera and gripper"><div class="lab-controls"><button data-part="frame">1 · Structure</button><button data-part="sensor">2 · Sensing</button><button data-part="controller">3 · Control</button><button data-part="actuator">4 · Action</button></div><p id="robot-part" class="callout" aria-live="polite">Select a group of parts to learn what they do.</p></div><div><label for="robot-context">Task</label><select id="robot-context">${Object.entries(contexts).map(([k,v])=>`<option value="${k}">${v.title}</option>`).join('')}</select>${Object.entries(choices).map(([key,opts])=>`<label for="robot-${key}">${key==='sensor'?'Sensor':key==='processor'?'Processing': 'Actuator'}</label><select id="robot-${key}"><option value="">Choose a component…</option>${opts.map(v=>`<option>${v}</option>`).join('')}</select>`).join('')}<div class="lab-controls"><button class="primary" id="robot-check">Check matches</button><button id="robot-reset">Reset</button></div><div id="robot-result" class="feedback" hidden aria-live="polite"></div></div></div>`;
 const el=id=>host.querySelector('#'+id),parts={frame:'Mechanical structure: the base, arm, joints and gripper support or handle objects. These are physical parts.',sensor:'Sensing: cameras and sensors collect data about objects or position. They send this data to the controller.',controller:'The controller runs a program, uses data to choose an action and sends signals. Programmable means its behaviour can be set using instructions.',actuator:'An actuator turns a control signal into a physical action. A motor turns a joint or opens and closes the gripper. The end-effector handles the object.'};
 host.querySelectorAll('[data-part]').forEach(btn=>btn.onclick=()=>{el('robot-part').textContent=parts[btn.dataset.part];host.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));});
 const clear=()=>{Object.keys(choices).forEach(k=>el('robot-'+k).value='');el('robot-result').hidden=true;};el('robot-context').onchange=clear;
 Object.keys(choices).forEach(k=>el('robot-'+k).onchange=()=>el('robot-result').hidden=true);
 el('robot-check').onclick=()=>{const ctx=contexts[el('robot-context').value],keys=Object.keys(choices),vals=keys.map(k=>el('robot-'+k).value),out=el('robot-result');out.hidden=false;if(vals.some(v=>!v)){out.textContent='Choose all three components before checking.';return;}const score=keys.filter(k=>el('robot-'+k).value===ctx[k]).length;out.innerHTML=`<b>${score}/3 choices match the described task.</b><p>${ctx.why}</p><p>Check: ${ctx.sensor} → ${ctx.processor} → ${ctx.actuator}.</p>`;};
 el('robot-reset').onclick=()=>{el('robot-context').value='warehouse';clear();el('robot-part').textContent='Select a group of parts to learn what they do.';host.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed','false'));};
},
expert(host){
 const facts=[{name:'Tram',surface:'rails',power:'electric'},{name:'Bicycle',surface:'road',power:'pedals'},{name:'Electric car',surface:'road',power:'electric'}];let stage=0;
 host.innerHTML=`<h2>Expert system: identify a vehicle</h2><div class="lab-grid"><div><h3>User interface</h3><label for="expert-surface">Where does the vehicle travel?</label><select id="expert-surface"><option value="">Unknown</option value="rails">Rails</option><option value="road">Road</option><option value="water">Water</option></select><label for="expert-power">What powers the vehicle?</label><select id="expert-power"><option value="">Unknown</option><option value="electric">Electric</option><option value="pedals">Pedals</option><option value="diesel">Diesel</option></select><div class="lab-controls"><button class="primary" id="expert-step">Next step</button><button id="expert-run">Show full cycle</button><button id="expert-reset">Reset</button></div><h3>Knowledge base</h3><div class="table-wrap"><table><thead><tr><th>Object</th><th>Surface</th><th>Power</th></tr></thead><tbody>${facts.map(f=>`<tr><td>${f.name}</td><td>${f.surface}</td><td>${f.power}</td></tr>`).join('')}</tbody></table></div><h3>Rule base</h3><ol>${facts.map(f=>`<li>IF surface = ${f.surface} AND power = ${f.power} THEN ${f.name}</li>`).join('')}</ol></div><div class="lab-result" id="expert-result" aria-live="polite"></div></div>`;
 const el=id=>host.querySelector('#'+id);
 const draw=()=>{const s=el('expert-surface').value,p=el('expert-power').value,match=facts.find(f=>f.surface===s&&f.power===p);let html='<h3>Inference engine · '+stage+'/4 steps</h3>';
  if(stage===0)html+='<p>Choose the facts, then follow the reasoning. There is no conclusion yet.</p>';
  if(stage>=1)html+=`<p><b>1. Receive facts through the interface:</b><br>surface = ${s||'unknown'}<br>power = ${p||'unknown'}</p>`;
  if(stage>=2)html+='<p><b>2. Use stored knowledge:</b> check the properties of the three vehicles in the knowledge base.</p>';
  if(stage>=3)html+=`<p><b>3. Check the rule base:</b></p><ol>${facts.map(f=>`<li>${f.name}: ${!s||!p?'not enough facts':f===match?'both conditions match':'the two conditions do not both match'}</li>`).join('')}</ol>`;
  if(stage>=4)html+=`<h3>4. Show the result through the interface</h3><p>${!s||!p?'More information is needed. Enter both surface and power to check the rules.':match?'Conclusion from this knowledge base: <b>'+match.name+'</b>.':'No rule matches. This knowledge base cannot identify the vehicle.'}</p>`;
  html+='<small>Only three vehicles are included. The system does not guess beyond its rules. Change the facts to try again.</small>';el('expert-result').innerHTML=html;};
 ['expert-surface','expert-power'].forEach(id=>el(id).onchange=()=>{stage=0;draw();});el('expert-step').onclick=()=>{stage=stage===4?1:stage+1;draw();};el('expert-run').onclick=()=>{stage=4;draw();};el('expert-reset').onclick=()=>{stage=0;el('expert-surface').value='';el('expert-power').value='';draw();};draw();
},
ml(host){
 const original=[{x:2,y:2,label:'A'},{x:3,y:3,label:'A'},{x:2,y:4,label:'A'},{x:6,y:6,label:'A'},{x:8,y:7,label:'B'},{x:8,y:4,label:'B'}];
 const tests=[{x:2,y:3,label:'A'},{x:8,y:6,label:'B'},{x:6,y:5,label:'B'},{x:3,y:2,label:'A'}];let training=original.map(v=>({...v})),model=null,done=false;
 const predict=(input,data)=>{let best=0,dist=Infinity;data.forEach((p,i)=>{const n=(input.x-p.x)**2+(input.y-p.y)**2;if(n<dist){dist=n;best=i;}});return {label:data[best].label,index:best};};
 host.innerHTML=`<h2>One input, two different sets of labels</h2><div class="lab-grid"><div><div id="ml-chart"></div><label>Feature 1: <output id="ml-x-out">6</output><input id="ml-x" type="range" min="0" max="10" step="1" value="6"></label><label>Feature 2: <output id="ml-y-out">5</output><input id="ml-y" type="range" min="0" max="10" step="1" value="5"></label><div class="lab-controls"><button class="primary" id="ml-train">Train & predict</button><button id="ml-reset">Reset</button></div><p class="source-note">The model uses the nearest example based on two features. If distances are equal, it uses the example with the lower number. You do not need to memorise the formula for Unit 6.</p></div><div><h3>Training data — select a label to change it</h3><div id="ml-data" class="table-wrap data-table"></div><div id="ml-result" class="feedback" aria-live="polite">Not trained yet. Predict the class of X before running the model.</div><details><summary>Four separate test examples</summary><div class="table-wrap"><table><thead><tr><th>X</th><th>Y</th><th>Correct label</th></tr></thead><tbody>${tests.map(t=>`<tr><td>${t.x}</td><td>${t.y}</td><td>${t.label}</td></tr>`).join('')}</tbody></table></div><p class="source-note">These examples are not used for training. Their labels are used only to check the predictions.</p></details></div></div>`;
 const el=id=>host.querySelector('#'+id),input=()=>({x:Number(el('ml-x').value),y:Number(el('ml-y').value)});
 const chart=()=>{const v=input(),px=x=>48+x*35,py=y=>380-y*33;el('ml-x-out').textContent=v.x;el('ml-y-out').textContent=v.y;el('ml-chart').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 430" role="img" aria-label="Six training examples and a new input X"><path d="M48 40 V380 H405" stroke="#698295" fill="none" stroke-width="2"/>${[0,2,4,6,8,10].map(n=>`<text x="${px(n)}" y="402" text-anchor="middle" font-size="13" fill="#486477">${n}</text><text x="31" y="${py(n)+5}" text-anchor="middle" font-size="13" fill="#486477">${n}</text>`).join('')}<text x="200" y="423" font-size="14" fill="#183247">Feature 1</text><text x="10" y="23" font-size="14" fill="#183247">Feature 2</text>${training.map((p,i)=>`${p.label==='A'?`<circle cx="${px(p.x)}" cy="${py(p.y)}" r="9" fill="#305ac8"/>`:`<rect x="${px(p.x)-9}" y="${py(p.y)-9}" width="18" height="18" fill="#bd790e"/>`}<text x="${px(p.x)+13}" y="${py(p.y)-9}" font-size="14" fill="#36566c">${i+1}</text>`).join('')}<path d="M${px(v.x)-9} ${py(v.y)-9} l18 18 M${px(v.x)-9} ${py(v.y)+9} l18 -18" stroke="#142c40" stroke-width="4"/><text x="${px(v.x)+13}" y="${py(v.y)+17}" font-size="16" fill="#142c40">X</text></svg><p class="source-note">● Blue = A · ■ Gold = B · × = new input (${v.x}, ${v.y})</p>`;};
 const result=()=>{if(!model){el('ml-result').innerHTML='The model is not trained, or a label has changed. Select “Train & predict” to use the current labels.';return;}const p=predict(input(),model),results=tests.map(t=>({...predict(t,model),truth:t.label})),score=results.filter(t=>t.label===t.truth).length;el('ml-result').innerHTML=`<h3>Prediction for X: ${p.label}</h3><p>Nearest training example: #${p.index+1} (${model[p.index].x}, ${model[p.index].y}), label ${model[p.index].label}.</p><p><b>Separate test set: ${score}/4 correct (${score*25}%).</b></p><p>${results.map((r,i)=>`Example ${i+1}: predicted ${r.label}, correct label ${r.truth} — ${r.label===r.truth?'correct':'incorrect'}`).join('<br>')}</p><p class="answer-status">This score applies only to these four test examples. Change the label of example #4 from A to B, keep X=(6,5), and train again.</p>`;};
 const data=()=>{el('ml-data').innerHTML=`<table><thead><tr><th>Example</th><th>(F1, F2)</th><th>Label</th></tr></thead><tbody>${training.map((p,i)=>`<tr><td>#${i+1}</td><td>(${p.x}, ${p.y})</td><td><button data-label="${i}" aria-label="Change the label of example ${i+1}, currently ${p.label}">${p.label} ↔</button></td></tr>`).join('')}</tbody></table>`;el('ml-data').querySelectorAll('[data-label]').forEach(btn=>btn.onclick=()=>{const p=training[Number(btn.dataset.label)];p.label=p.label==='A'?'B':'A';model=null;data();chart();result();});};
 ['ml-x','ml-y'].forEach(id=>el(id).oninput=()=>{chart();if(done)result();});el('ml-train').onclick=()=>{model=training.map(p=>({...p}));done=true;chart();result();};el('ml-reset').onclick=()=>{training=original.map(p=>({...p}));model=null;done=false;el('ml-x').value=6;el('ml-y').value=5;data();chart();el('ml-result').textContent='Not trained yet. Predict the class of X before running the model.';};data();chart();
}
};
